package com.sakti.banking.dto; import com.sakti.banking.entity.*; import java.time.*; public record UserResponse(Long id,String fullName,String email,Role role,boolean enabled,String phone,String address,LocalDate dateOfBirth,String nomineeName,String nomineeRelation,KycStatus kycStatus,LocalDateTime createdAt){ public static UserResponse from(AppUser u){return new UserResponse(u.getId(),u.getFullName(),u.getEmail(),u.getRole(),u.isEnabled(),u.getPhone(),u.getAddress(),u.getDateOfBirth(),u.getNomineeName(),u.getNomineeRelation(),u.getKycStatus(),u.getCreatedAt());}}